  const request = { scope: fixture.scope, selection, instruction: '检查这个事件是否只是计划；保持其他字段',
    modelIdentity: { provider: 'fixture', model: 'test-only' }, runAI: vi.fn(async () => ({ output: draft, durationMs: 1 })) }
  return { fixture, request, draft }
}

